"""Build the submission from saved evidence only. No models or network calls."""
from pathlib import Path
import hashlib
import json
import re

ROOT = Path(__file__).resolve().parents[1]
FINAL = ROOT / 'results/final'
BLOCKS = []
SOURCES = []

def h(text, level=1):
    BLOCKS.append(dict(kind='h', text=text, level=level))

def p(text):
    BLOCKS.append(dict(kind='p', text=text))

def table(headers, rows, widths=None):
    BLOCKS.append(dict(kind='table', headers=headers,
                       rows=[[str(c) for c in row] for row in rows], widths=widths))

def figure(name, caption, folder=FINAL):
    path = folder / name
    if not path.is_file():
        raise FileNotFoundError(path)
    BLOCKS.append(dict(kind='figure', path=str(path), caption=caption))

def code(name, title=None, folder=ROOT/'scripts'):
    path = folder / name
    source = path.read_text(encoding='utf-8')
    p('Листинг — ' + (title or name) + '. Полный исходный текст файла ' + name + '.')
    BLOCKS.append(dict(kind='code', text=source))
    SOURCES.append(dict(file=str(path.relative_to(ROOT.parent)),
                        sha256=hashlib.sha256(source.encode()).hexdigest(), lines=len(source.splitlines())))

def data(name):
    return json.loads((FINAL / (name + '.json')).read_text(encoding='utf-8'))

def algorithm(text):
    p('Алгоритм выполнения. ' + text)

def main():
    h('Цель работы')
    p('Освоить прикладные методы компьютерного зрения: оценку ключевых точек, сопровождение объектов, коррекцию дисторсии, оптический поток, сверхразрешение, распознавание текста, поиск по признакам, обучение метрики, zero-shot-модели, поиск момента в видео, подготовку разметки и учёт экспериментов. Основной объект исследования — изображения бледной трепонемы Treponema pallidum. Структура практических разделов соответствует частям 2–10 методических указаний к лабораторной работе № 4.')
    p('Для каждого метода рассматриваются входные данные, последовательность вычислений, программа и выходные артефакты. Численные результаты сопоставляются с изображениями: высокая скорость, наличие рамки или большое сходство эмбеддингов сами по себе не означают точного определения границ и вида бактерии.')

    h('1. Общая схема и подготовка')
    h('1.1. Объект исследования и особенности изображений', 2)
    p('Бледная трепонема относится к спирохетам: её характерный визуальный признак — тонкая вытянутая спиралевидная форма. При анализе изображений внимание уделяется извилистому контуру, непрерывности осевой линии и изменению формы между кадрами. На двумерной проекции отдельные участки могут перекрываться или выходить за границу изображения. Поэтому связная область маски далее называется видимым фрагментом, а число таких областей характеризует изображение, а не число биологических клеток.')
    p('Основное изображение взято по заданной ссылке pcr.news. Это цветная иллюстрация размером 870 × 540 пикселей с хорошо различимыми спиралевидными объектами. Она используется для контролируемых геометрических опытов, выделения маски, формирования ключевых точек и обучения pose-моделей. Дополнительные микрофотографии Treponema pallidum позволяют сравнить внешний вид объекта при разных способах получения изображения. Видео t07.ogv содержит микроскопическую съёмку спирохет из исторического фильма Жана Командона.')
    p('Работа с бактерией в этой лабораторной означает обработку цифровых изображений. Сначала сохраняются исходные файлы и сведения об источниках, затем выбираются представление цвета и пространственная область анализа. Для цветной иллюстрации удобна маска по каналам BGR и HSV; для микроскопического видео — яркость, градиенты и временное смещение. Все длины и скорости рассчитываются в пикселях и пикселях в секунду. Физический масштаб задаётся только при наличии известной калибровки конкретного изображения.')
    p('Перед выделением объектов изображение читается OpenCV в порядке BGR. Для нейросетей и вывода через Matplotlib оно преобразуется в RGB. Маска очищается от небольших областей и отверстий, затем выполняется морфологическое замыкание. У каждой крупной компоненты определяются рамка, площадь и осевая линия. Для спиралевидного объекта центральная точка выбирается по половине длины этой линии: она сохраняет связь с формой объекта при изгибе.')
    figure('treponema_primary.jpg', 'Основное изображение Treponema pallidum, использованное в работе', ROOT/'data/raw')
    figure('sources_contact.png', 'Дополнительные изображения Treponema pallidum из открытых источников', ROOT/'results')
    sources=json.loads((ROOT/'data/raw/sources.json').read_text())
    table(['Файл', 'Размер', 'Материал и источник'], [[s['file'],f"{s['width']} × {s['height']}",re.sub('<[^>]+>','',s['artist'])+'; '+s['license']] for s in sources], [.18,.18,.64])
    h('1.2. Данные, разбиение и программная среда', 2)
    p('Дополнительные палочковидные бактерии и кокки используются как классы сравнения для поиска и классификации. Контрольный снимок людей bus.jpg нужен для проверки моделей, обученных на человеческом скелете. Эти материалы позволяют отделить работоспособность программного конвейера от переноса модели на новый тип объекта.')
    table(['Набор', 'Состав', 'Назначение'], [
        ['Основной снимок','870 × 540, 6 крупных компонент','Маска, скелет, геометрия, zero-shot'],
        ['Галерея поиска','80 изображений 224 × 224','40 train, 15 validation, 25 test'],
        ['Набор YOLO-pose','32 train, 4 validation, 4 test','Варианты шести видимых фрагментов'],
        ['Видео t07.ogv','Кадры 360 × 288; отрезок с 36 с','Трекинг и оптический поток'],
        ['Видео RuTube','81 индексированный кадр','Поиск по тексту в Streamlit']])
    p('В галерее разделение выполняется по исходным файлам: фрагменты одного источника попадают в одну часть набора. Близкие варианты t04 и t05 оставлены вместе в train. В pose-наборе сначала распределяются шесть исходных компонент, а затем выполняется преобразование масштаба и положения. Четыре компоненты формируют train, одна validation и одна test. Такой набор проверяет учебный цикл на одной иллюстрации; его метрики описывают именно эти видимые фрагменты.')
    p('Вычисления выполнены на CPU с фиксированным seed = 7. Используются PyTorch, Ultralytics, Transformers, OpenCV contrib, MediaPipe Tasks, scikit-image, scikit-learn, MLflow, EasyOCR и Tesseract. В окружении оставляется один пакет OpenCV с contrib-модулями, поскольку SOT-трекеры доступны через cv2.legacy. Вспомогательные пути и параметры потоков вынесены в общий модуль experiment_common.py.')
    algorithm('1) Сохранить исходные изображения и видео. 2) Проверить размеры и порядок каналов. 3) Сформировать маску и крупные компоненты. 4) Разделить источники на train, validation и test. 5) Задать seed и каталоги результатов. 6) Сохранять численные наблюдения в JSON, изображения в PNG, модели в PT и историю обучения в CSV.')
    p('Входные файлы находятся в data/raw, подготовленные наборы — в data/final_gallery и data/final_pose. Выходные данные отдельных опытов сохранены в results/final. Каталоги с загружаемыми весами и служебным кешем отделены от результатов. Для воспроизведения сначала устанавливаются зависимости из requirements.txt, затем подготавливаются официальные веса моделей. Программы ниже приведены полностью; общий модуль используется всеми экспериментальными сценариями.')
    code('experiment_common.py', 'Общие пути, сохранение результатов и выделение точек осевой линии')
    code('prepare_primary.py', 'Подготовка цветовой маски основного изображения')
    code('prepare_models.py', 'Подготовка весов моделей')

    h('2. Ключевые точки: YOLO-pose и MediaPipe')
    h('2.1. Контроль на изображении людей и перенос на бактерии', 2)
    p('Ключевая точка задаёт место объекта с постоянным смыслом. Для человека стандарт COCO содержит 17 точек, а MediaPipe Pose — 33. Для каждого найденного объекта получаются координаты точек и оценки уверенности. Контроль на изображении людей показывает, какие структуры распознаёт исходная модель до адаптации к бактериям.')
    algorithm('1) Загрузить YOLOv8s-pose. 2) Обработать bus.jpg при conf = 0,5. 3) Обработать основное изображение при conf = 0,5; 0,25; 0,05. 4) Сохранить число рамок и изображение со скелетами. 5) Создать MediaPipe PoseLandmarker с моделью lite. 6) Преобразовать координаты MediaPipe из долей ширины и высоты в пиксели и отобразить точки.')
    controls=data('human_controls')
    table(['Вход и модель','Порог','Объектов','Точек в схеме'],[
        ['YOLOv8s-pose, люди','0,5',controls['people_0.5']['boxes'],17],
        *[['YOLOv8s-pose, трепонема',str(c),controls[f'treponema_{c}']['boxes'],17] for c in [.5,.25,.05]],
        ['MediaPipe lite, люди','По умолчанию',controls['mediapipe_people']['people'],33],
        ['MediaPipe lite, трепонема','По умолчанию',controls['mediapipe_treponema']['people'],33]])
    figure('human_pose.png','YOLOv8s-pose: люди и Treponema pallidum при трёх порогах уверенности')
    figure('mediapipe.png','MediaPipe Pose Landmarker: точки тела на контрольном снимке и обработка изображения трепонемы')
    p('На изображении людей YOLOv8s-pose выделяет четыре объекта, MediaPipe — одного человека. На иллюстрации трепонемы при порогах 0,5 и 0,25 число рамок YOLO равно нулю, а при 0,05 возникают пять срабатываний человеческой модели. Это демонстрирует влияние порога: снижение conf увеличивает число кандидатов, однако значения точек продолжают соответствовать человеческой схеме. Для бактерии нужна собственная разметка и адаптация pose-модели.')
    h('2.2. Схема «начало — середина — конец»', 2)
    p('Для каждого видимого фрагмента выделяется тонкий скелет маски. Его пиксели образуют граф: соседние по стороне пиксели соединены ребром длины 1, по диагонали — √2. Два прохода алгоритма Дейкстры дают длинный достижимый путь по осевой линии. Точка 0 лежит на одном конце пути, точка 1 — на половине его накопленной длины, точка 2 — на другом конце. Порядок концов фиксируется сравнением координат.')
    p('Методичка предлагает главную ось полигона для палочковидной формы. Здесь та же схема из трёх точек адаптирована к спиралевидной трепонеме через осевую линию. Расстояние между крайними точками L характеризует хорду; сумма длин шагов скелета характеризует длину видимого извилистого фрагмента. Эти величины различаются и используются в разных расчётах.')
    figure('skeleton_landmarks.png','Маска и три ключевые точки, расположенные вдоль осевой линии трепонемы')
    records=data('skeleton_landmarks')
    table(['Компонента','Площадь, px²','Длина осевой линии, px','Начало; середина; конец'],[[r['id'],r['area_px'],f"{r['arc_length_px']:.2f}",'; '.join(f'({x:.0f}, {y:.0f})' for x,y in r['keypoints'])] for r in records],[.13,.18,.2,.49])
    p('Строка YOLO-pose содержит 14 чисел: класс, центр и размеры рамки, затем три тройки (x, y, v). Координаты нормируются на размеры изображения. Видимость v = 2 означает видимую точку, v = 1 — закрытую, v = 0 — отсутствующую. В конфигурации kpt_shape = [3, 3], flip_idx = [2, 1, 0]. При отражении по горизонтали меняются местами концы, центральная точка остаётся центральной.')
    h('2.3. Сопровождение и счётчик изменения формы', 2)
    p('Для последовательности кадров программа связывает рамки через ByteTrack и хранит состояние по идентификатору трека. Изогнутость вычисляется как κ = |(p₂ − p₀) × (p₁ − p₀)| / L², где L = ‖p₂ − p₀‖. Наивный счётчик увеличивается в каждом кадре с изогнутой формой. Счётчик переходов увеличивается только при переходе из прямого состояния в изогнутое. Порог входа 0,10 и порог выхода 0,07 образуют гистерезис, уменьшающий дрожание состояния.')
    algorithm('1) Открыть локальный видеофайл. 2) Для каждого кадра вызвать model.track с persist=True. 3) Сопоставить точки и ID трека. 4) Вычислить изогнутость. 5) Обновить состояние и два счётчика. 6) Вычислить среднее значение FPS по окну последних 15 кадров. 7) Сохранить наблюдения и контрольные кадры.')
    p('Листинг run_video_checks.py содержит обработку локального видео, поиск по тексту и изображению и реализацию счётчиков. Его выходной формат включает ID, номер кадра, изогнутость, число переходов и FPS. Количественное сравнение выполненного сопровождения четырьмя SOT-трекерами представлено в разделе 3; оценки pose-моделей на отложенных изображениях — в разделе 10.')
    code('run_video_checks.py','Поиск в локальном видео и счётчики по ключевым точкам')
