    table(['Запуск дерева','Validation macro-F1','Test macro-F1'],[[x['name'],f"{x['val_f1']:.6f}",f"{x['test_f1']:.6f}"] for x in ml['trees']])
    table(['Запуск MLP','Последняя val accuracy','Test macro-F1','Повторная загрузка'],[[x['name'],f"{x['val_history'][-1]:.6f}",f"{x['test_f1']:.6f}",'Совпадение' if x['reload_identical'] else 'Различие'] for x in ml['networks']])
